(4156312, 598427, 43073, '<td valign="top">I like the perspective (from underneath) and the depth of field, and the subtle contrasts of shades of yellow here.</td>', 'I like the perspective (from underneath) and the depth of field, and the subtle contrasts of shades of yellow here.', '2007-10-10 03:07:49.000000', NULL, 1),
(4156314, 598051, 70000, '<td valign="top">beautiful rose! the extra petals off to the side really make this, great color scheme, the border seems tacky to me though, the picture has beautiful muted colors and the pink around the frame looks too bring compared to the rest of the photo</td>', 'beautiful rose! the extra petals off to the side really make this, great color scheme, the border seems tacky to me though, the picture has beautiful muted colors and the pink around the frame looks too bring compared to the rest of the photo', '2007-10-10 03:08:15.000000', NULL, 1),
(4156316, 598168, 70000, '<td valign="top">the giant out of focus flower near the middle of the photo holds too much attention in my opinion. the background flowers that are in focus are cute and flighty and I would have liked to have seen more attention on them</td>', 'the giant out of focus flower near the middle of the photo holds too much attention in my opinion. the background flowers that are in focus are cute and flighty and I would have liked to have seen more attention on them', '2007-10-10 03:09:01.000000', NULL, 1),
(4156319, 596626, 70000, '<td valign="top">wonderful sharp focus on the thorns, i like the diagonal in the shot as well</td>', 'wonderful sharp focus on the thorns, i like the diagonal in the shot as well', '2007-10-10 03:10:10.000000', NULL, 1),
(4156320, 597332, 70000, '<td valign="top">wonderful lighting but the shaded parts are colored funny and seem noisy, this would probably look better as a black and white</td>', 'wonderful lighting but the shaded parts are colored funny and seem noisy, this would probably look better as a black and white', '2007-10-10 03:10:47.000000', NULL, 1),
(4156323, 598413, 43073, '<td valign="top">Lovely juxtaposition of "real" beauty with (what at least appears to be) "artificial" beauty in the fake flower; the smile makes this for me.</td>', 'Lovely juxtaposition of "real" beauty with (what at least appears to be) "artificial" beauty in the fake flower; the smile makes this for me.', '2007-10-10 03:12:57.000000', NULL, 1),
(4156327, 597967, 70000, '<td valign="top">Lovely colors here, the composition gets kind of cluttered in the corner but these are pretty details</td>', 'Lovely colors here, the composition gets kind of cluttered in the corner but these are pretty details', '2007-10-10 03:16:30.000000', NULL, 1),
(4156331, 597558, 43073, '<td valign="top">Interesting take on the challenge to show something for some reason other than "it''s pretty", but to show it as is, flaws and all, "working", though the lighting here is a bit harsh.</td>', 'Interesting take on the challenge to show something for some reason other than "it''s pretty", but to show it as is, flaws and all, "working", though the lighting here is a bit harsh.', '2007-10-10 03:20:51.000000', NULL, 1),
