(4156776, 597921, 83758, '<td valign="top">I like the inspiration and courage of your work... whilst I think it is a photograph of quality, unfortunately it is not the type of bubblegum shot that appeals to the average voter on DPC. Pity - I have given it a 9... well done. I would like to know what your setup and processing was. - Mike</td>', 'I like the inspiration and courage of your work... whilst I think it is a photograph of quality, unfortunately it is not the type of bubblegum shot that appeals to the average voter on DPC. Pity - I have given it a 9... well done. I would like to know what your setup and processing was. - Mike', '2007-10-10 08:00:11.000000', NULL, 1),
(4156781, 597921, 53147, '<td valign="top">Interesting. Not pretty but intriguing. Especially amongst all the flowers. 8</td>', 'Interesting. Not pretty but intriguing. Especially amongst all the flowers. 8', '2007-10-10 08:06:31.000000', NULL, 1),
(4156787, 597312, 53147, '<td valign="top">I would just like to say that this image stands out well amongst all the color and typical images seen in this challenge. THere were only a few that went a route that didnt present the "pretty". Those few are a refreshing break. Thank you!</td>', 'I would just like to say that this image stands out well amongst all the color and typical images seen in this challenge. THere were only a few that went a route that didnt present the "pretty". Those few are a refreshing break. Thank you!', '2007-10-10 08:14:21.000000', NULL, 1),
(4156896, 597569, 15711, '<td valign="top">Very nice.  I like the warm sepia tones.</td>', 'Very nice.  I like the warm sepia tones.', '2007-10-10 09:32:23.000000', NULL, 1),
(4156899, 598051, 15711, '<td valign="top">I think the deep pink of the border distracts our eye away from the beautiful bloom. I might have it a bit less centered. Nice focus and DOF.</td>', 'I think the deep pink of the border distracts our eye away from the beautiful bloom. I might have it a bit less centered. Nice focus and DOF.', '2007-10-10 09:33:38.000000', NULL, 1),
(4156901, 597312, 15711, '<td valign="top">Love this.  It is artfully done.</td>', 'Love this.  It is artfully done.', '2007-10-10 09:34:07.000000', NULL, 1),
