(4156928, 597645, 41675, '<td valign="top">To me, the lighting is a little harsh at the bottom. Nicy array of flora.</td>', 'To me, the lighting is a little harsh at the bottom. Nicy array of flora.', '2007-10-10 09:47:23.000000', NULL, 1),
(4156930, 596165, 41675, '<td valign="top">For me, I wonder how this would look if cropped in from the left - so the flower wouldn''t be "dead" center? I do like your color tones.</td>', 'For me, I wonder how this would look if cropped in from the left - so the flower wouldn''t be "dead" center? I do like your color tones.', '2007-10-10 09:48:18.000000', NULL, 1),
(4156933, 598162, 41675, '<td valign="top">I really wish your image size were larger - make sure you take full advantage of the allowable pixels. The little hairs look soft. Good lighting too.</td>', 'I really wish your image size were larger - make sure you take full advantage of the allowable pixels. The little hairs look soft. Good lighting too.', '2007-10-10 09:49:19.000000', NULL, 1),
(4156940, 598187, 41675, '<td valign="top">Great color contrast, the background blue complilments the green well. The curls are interesting. The black border is a little too thick for my personal taste, but a terrific photo overall.</td>', 'Great color contrast, the background blue complilments the green well. The curls are interesting. The black border is a little too thick for my personal taste, but a terrific photo overall.', '2007-10-10 09:51:13.000000', NULL, 1),
(4156942, 596217, 41675, '<td valign="top">I like the composition and colors. Shucks! The gnome must be inside.</td>', 'I like the composition and colors. Shucks! The gnome must be inside.', '2007-10-10 09:52:00.000000', NULL, 1),
(4156946, 596486, 41675, '<td valign="top">The fruit seems purposely placed, but it does add a nice balance for the flower and the mushroom. Good lighting.</td>', 'The fruit seems purposely placed, but it does add a nice balance for the flower and the mushroom. Good lighting.', '2007-10-10 09:53:25.000000', NULL, 1),
(4156948, 595194, 41675, '<td valign="top">Nice image. I like the black background - it really makes the colors of the floweer pop.</td>', 'Nice image. I like the black background - it really makes the colors of the floweer pop.', '2007-10-10 09:54:14.000000', NULL, 1),
(4156950, 598154, 41675, '<td valign="top">Lol - I like your title. Great natural lighting and good composition. Another pretty flower shot.</td>', 'Lol - I like your title. Great natural lighting and good composition. Another pretty flower shot.', '2007-10-10 09:55:00.000000', NULL, 1),
(4156952, 596656, 41675, '<td valign="top">Good leaf shot. It would make a good background.</td>', 'Good leaf shot. It would make a good background.', '2007-10-10 09:55:51.000000', NULL, 1),
