(4163685, 596853, 26001, '<td valign="top">beautiful minimalistic photo and excellent colors. with the dof was a little more and the whole leaf was in focus. still 9 from me.</td>', 'beautiful minimalistic photo and excellent colors. with the dof was a little more and the whole leaf was in focus. still 9 from me.', '2007-10-12 19:32:32.000000', NULL, 1),
(4163689, 595544, 26001, '<td valign="top">probably my most favourite shot of the challenge. brilliantly lit 10</td>', 'probably my most favourite shot of the challenge. brilliantly lit 10', '2007-10-12 19:33:26.000000', NULL, 1),
(4163690, 598022, 26001, '<td valign="top">superb lighting 9</td>', 'superb lighting 9', '2007-10-12 19:34:35.000000', NULL, 1),
(4163714, 595802, 65234, '<td valign="top">Nice, subtle colors.  The difference between the background and lighter parts of the flowers is sometimes difficult to see (on my monitor); a light aimed at the background or more distance between flowers and background might work better.</td>', 'Nice, subtle colors.  The difference between the background and lighter parts of the flowers is sometimes difficult to see (on my monitor); a light aimed at the background or more distance between flowers and background might work better.', '2007-10-12 19:44:23.000000', NULL, 1),
(4163719, 596645, 65234, '<td valign="top">Nice job with focus and DOF to clearly differentiate white on white so the curves and lines of the flower are apparent.</td>', 'Nice job with focus and DOF to clearly differentiate white on white so the curves and lines of the flower are apparent.', '2007-10-12 19:47:44.000000', NULL, 1),
(4163722, 597298, 65234, '<td valign="top">Detail and color are good; composition is OK.  Yellow flower bits (pistils or stamens or something ... I never remember flower parts) look a little oversharpened, but look like they would be an interesting thing to do a macro of.</td>', 'Detail and color are good; composition is OK.  Yellow flower bits (pistils or stamens or something ... I never remember flower parts) look a little oversharpened, but look like they would be an interesting thing to do a macro of.', '2007-10-12 19:52:02.000000', NULL, 1),
(4163723, 597870, 65234, '<td valign="top">Nice stop-action on the water. Flowers look a bit overexposed on my monitor.</td>', 'Nice stop-action on the water. Flowers look a bit overexposed on my monitor.', '2007-10-12 19:53:09.000000', NULL, 1),
(4163725, 597442, 65234, '<td valign="top">Pretty; interesting shapes and DOF and I like how that bit of orange in the background echoes the orange in the flower.</td>', 'Pretty; interesting shapes and DOF and I like how that bit of orange in the background echoes the orange in the flower.', '2007-10-12 19:54:33.000000', NULL, 1),
(4163735, 596938, 65234, '<td valign="top">Interesting flower and I like the contrast between the softness of the flower and the prockly spines.  I might crop a good deal more off the left so the flower is pointed more at the upper left corner.</td>', 'Interesting flower and I like the contrast between the softness of the flower and the prockly spines.  I might crop a good deal more off the left so the flower is pointed more at the upper left corner.', '2007-10-12 20:01:30.000000', NULL, 1),
(4163737, 598302, 65234, '<td valign="top">Honeysuckle?  Nice bokeh in the background :-)</td>', 'Honeysuckle?  Nice bokeh in the background :-)', '2007-10-12 20:02:48.000000', NULL, 1),
(4163790, 597858, 65234, '<td valign="top">Jethro Tull?!  I think that car''s too old even for that group ;-)  Nice find for this challenge, though, and the red of the car nicely brings out the leaves that are starting to turn.</td>', 'Jethro Tull?!  I think that car''s too old even for that group ;-)  Nice find for this challenge, though, and the red of the car nicely brings out the leaves that are starting to turn.', '2007-10-12 21:06:31.000000', NULL, 1),
