(4165840, 597921, 39430, '<td valign="top">Interesting effect, but I don''t think it will be popular in the vote.</td>', 'Interesting effect, but I don''t think it will be popular in the vote.', '2007-10-14 01:06:56.000000', NULL, 1),
(4165846, 597309, 39430, '<td valign="top">Technically excellent, and a very interesting subject.  This is a wierd looking fungus, like a pile of alien larvae.  :)  Some spots of dappled orange sunlight on the RHS would perfect this for me.</td>', 'Technically excellent, and a very interesting subject.  This is a wierd looking fungus, like a pile of alien larvae.  :)  Some spots of dappled orange sunlight on the RHS would perfect this for me.', '2007-10-14 01:10:28.000000', NULL, 1),
(4165847, 598048, 39430, '<td valign="top">The flower is a little small in the fram, and I''m not so keep on the border, but overall not bad.</td>', 'The flower is a little small in the fram, and I''m not so keep on the border, but overall not bad.', '2007-10-14 01:11:08.000000', NULL, 1),
(4165852, 596458, 39430, '<td valign="top">Very expressive.  WB is a little too blue.  Focus is good.</td>', 'Very expressive.  WB is a little too blue.  Focus is good.', '2007-10-14 01:16:41.000000', NULL, 1),
(4165853, 597594, 39430, '<td valign="top">Nice background to complement the subject.</td>', 'Nice background to complement the subject.', '2007-10-14 01:19:26.000000', NULL, 1),
(4165854, 597460, 39430, '<td valign="top">Something about the colours and contrast makes it look like a recoloured negative image.  Kinda wierd.</td>', 'Something about the colours and contrast makes it look like a recoloured negative image.  Kinda wierd.', '2007-10-14 01:21:57.000000', NULL, 1),
(4165855, 597798, 39430, '<td valign="top">Very nice colours and lines.  So smooth, like a painting.</td>', 'Very nice colours and lines.  So smooth, like a painting.', '2007-10-14 01:22:37.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4165856, 596218, 39430, '<td valign="top">I''ve got no idea what the title means, but a nicely balanced photo.  I like the not-quite symmetry.</td>', 'I''ve got no idea what the title means, but a nicely balanced photo.  I like the not-quite symmetry.', '2007-10-14 01:24:21.000000', NULL, 1),
(4165857, 598324, 39430, '<td valign="top">Nicely lit texture.</td>', 'Nicely lit texture.', '2007-10-14 01:25:00.000000', NULL, 1),
(4165858, 595439, 39430, '<td valign="top">A bit too blown for my liking.  Nice detail though.</td>', 'A bit too blown for my liking.  Nice detail though.', '2007-10-14 01:25:50.000000', NULL, 1),
(4165870, 598393, 39430, '<td valign="top">C''est bon, mais peut-étre un petit peut foncé.  OK, that''s exhausted my french.  :)  Nice impressionistic background.</td>', 'C''est bon, mais peut-étre un petit peut foncé.  OK, that''s exhausted my french.  :)  Nice impressionistic background.', '2007-10-14 01:31:07.000000', NULL, 1),
(4165895, 597302, 39430, '<td valign="top">Looks a little noisy.  Perhaps it was shot underexposed and pushed in PP?  If so, it would have been better exposed correctly in the camera.</td>', 'Looks a little noisy.  Perhaps it was shot underexposed and pushed in PP?  If so, it would have been better exposed correctly in the camera.', '2007-10-14 01:46:48.000000', NULL, 1),
(4165898, 595602, 39430, '<td valign="top">Very creative.  I would probably have cropped the left hand side off the image and gone for a squarer shot.</td>', 'Very creative.  I would probably have cropped the left hand side off the image and gone for a squarer shot.', '2007-10-14 01:48:01.000000', NULL, 1),
(4166080, 596255, 79532, '<td valign="top">Very nice use of Shallow depth. only crit would be the flower''s a bit dark bottom right wich seems to contra the darkness from the background.</td>', 'Very nice use of Shallow depth. only crit would be the flower''s a bit dark bottom right wich seems to contra the darkness from the background.', '2007-10-14 03:23:23.000000', NULL, 1),
(4166082, 598075, 79532, '<td valign="top">Nice colours, try to avoid the hot spots caused by the flash. Some flowers tend to blow the picture.</td>', 'Nice colours, try to avoid the hot spots caused by the flash. Some flowers tend to blow the picture.', '2007-10-14 03:24:38.000000', NULL, 1),
(4166084, 598411, 79532, '<td valign="top">Not bad, tree maybe a bit too dark, could have used a bit more definition.  Could have been the time of day you took the picture.</td>', 'Not bad, tree maybe a bit too dark, could have used a bit more definition.  Could have been the time of day you took the picture.', '2007-10-14 03:26:07.000000', NULL, 1),
(4166087, 597671, 79532, '<td valign="top">Stunning Picture, I''d have tried to keep Content and framing alittle off center, great colours and DOF.</td>', 'Stunning Picture, I''d have tried to keep Content and framing alittle off center, great colours and DOF.', '2007-10-14 03:28:18.000000', NULL, 1),
(4166089, 596153, 79532, '<td valign="top">Interesting idea, the light spots do make it a bit distracting, Nice lead from the leaf, little too grainy in you OOF area not sure of the ISO ur using. could have been set too high.</td>', 'Interesting idea, the light spots do make it a bit distracting, Nice lead from the leaf, little too grainy in you OOF area not sure of the ISO ur using. could have been set too high.', '2007-10-14 03:30:55.000000', NULL, 1),
(4166092, 596084, 79532, '<td valign="top">Very interesting Flowers, a few crits,  the Center of the flowers are a little too dark could be compensation for the bright white/ blue the flowers giving. and the last petal slightly blown (bottom right). else great detail.</td>', 'Very interesting Flowers, a few crits,  the Center of the flowers are a little too dark could be compensation for the bright white/ blue the flowers giving. and the last petal slightly blown (bottom right). else great detail.', '2007-10-14 03:33:29.000000', NULL, 1),
(4166094, 598101, 79532, '<td valign="top">Nice Picture, Just watch the sun''s hot spots, can sometimes cause a distraction.. (bottom Right)</td>', 'Nice Picture, Just watch the sun''s hot spots, can sometimes cause a distraction.. (bottom Right)', '2007-10-14 03:34:33.000000', NULL, 1),
(4166095, 597666, 79532, '<td valign="top">Lovely Shot. Nice colours and detail.</td>', 'Lovely Shot. Nice colours and detail.', '2007-10-14 03:35:38.000000', NULL, 1),
(4166097, 596892, 79532, '<td valign="top">Little soft on the flower.</td>', 'Little soft on the flower.', '2007-10-14 03:36:46.000000', NULL, 1),
(4166100, 597691, 79532, '<td valign="top">Nice shot, I''d probably have cropped tighter onto the flower though little too much "Dead space" even if OOF effect is eligant.</td>', 'Nice shot, I''d probably have cropped tighter onto the flower though little too much "Dead space" even if OOF effect is eligant.', '2007-10-14 03:38:21.000000', NULL, 1),
(4166102, 598094, 79532, '<td valign="top">Shadow on the bottom right tends to distract a bit. Picture abit Grainy.</td>', 'Shadow on the bottom right tends to distract a bit. Picture abit Grainy.', '2007-10-14 03:39:43.000000', NULL, 1),
(4166103, 596954, 79532, '<td valign="top">nice colours, wouldn''t have cut the flower though.</td>', 'nice colours, wouldn''t have cut the flower though.', '2007-10-14 03:40:46.000000', NULL, 1),
(4166107, 597798, 79532, '<td valign="top">Not really much to go on in this composition, Probably as I can''t make out what your focal point is.  Nice DOF though. Shadow on Right reed a bit distracting.</td>', 'Not really much to go on in this composition, Probably as I can''t make out what your focal point is.  Nice DOF though. Shadow on Right reed a bit distracting.', '2007-10-14 03:43:00.000000', NULL, 1),
(4166108, 595484, 79532, '<td valign="top">Nice shot, Would have used a white balance though, the flash is highlighting the white a bit too much.</td>', 'Nice shot, Would have used a white balance though, the flash is highlighting the white a bit too much.', '2007-10-14 03:44:10.000000', NULL, 1),
(4166110, 596780, 79532, '<td valign="top">Nice idea, Subject a bit too dark in the center.</td>', 'Nice idea, Subject a bit too dark in the center.', '2007-10-14 03:46:16.000000', NULL, 1),
(4166112, 598215, 79532, '<td valign="top">Colour a little over exposed on the bottom of the flower, tends to loose detail.</td>', 'Colour a little over exposed on the bottom of the flower, tends to loose detail.', '2007-10-14 03:48:19.000000', NULL, 1),
(4166113, 598326, 79532, '<td valign="top">It took me some time to see the vine on the wall.  Picture''s tone is too dark. your subject not really highlighted.</td>', 'It took me some time to see the vine on the wall.  Picture''s tone is too dark. your subject not really highlighted.', '2007-10-14 03:49:48.000000', NULL, 1),
(4166114, 597904, 79532, '<td valign="top">Just slightly blown on the white.</td>', 'Just slightly blown on the white.', '2007-10-14 03:50:30.000000', NULL, 1),
(4166119, 598133, 79532, '<td valign="top">Very nice Macro, Flower has great colours, only distaction are the top two Darker area''s, and maybe would have positioned flower alittle more off centre.</td>', 'Very nice Macro, Flower has great colours, only distaction are the top two Darker area''s, and maybe would have positioned flower alittle more off centre.', '2007-10-14 03:52:58.000000', NULL, 1),
(4166121, 595167, 79532, '<td valign="top">Not a bad shot, Just the sharpness isn''t present and shadow on the flowers a bit distracting.</td>', 'Not a bad shot, Just the sharpness isn''t present and shadow on the flowers a bit distracting.', '2007-10-14 03:54:52.000000', NULL, 1),
(4166127, 598260, 79532, '<td valign="top">Would have maybe used a bit more green or a flower to illistrate..</td>', 'Would have maybe used a bit more green or a flower to illistrate..', '2007-10-14 03:57:35.000000', NULL, 1),
(4166131, 596523, 79532, '<td valign="top">Nice Colours in the Iris. I''d watch the hotspots though, Can be a challenging flower to take as the white tends to cause a major contrast to the rest of the colours.  Tru under expose a little and maybe increase Brightness.  Also be careful not to cut the flower, would have pushed it a tad higher.</td>', 'Nice Colours in the Iris. I''d watch the hotspots though, Can be a challenging flower to take as the white tends to cause a major contrast to the rest of the colours.  Tru under expose a little and maybe increase Brightness.  Also be careful not to cut the flower, would have pushed it a tad higher.', '2007-10-14 04:00:49.000000', NULL, 1),
(4166132, 596194, 79532, '<td valign="top">Flowers in the forground are a bit over exposed on the colour, Nice Pattern effect for the background.</td>', 'Flowers in the forground are a bit over exposed on the colour, Nice Pattern effect for the background.', '2007-10-14 04:02:20.000000', NULL, 1),
(4166133, 598187, 37444, '<td valign="top">It''s such a nice image but that frame is awfully distracting. 8</td>', 'It''s such a nice image but that frame is awfully distracting. 8', '2007-10-14 04:02:40.000000', NULL, 1),
(4166134, 596133, 83623, '<td valign="top">so so pretty! I love it :]</td>', 'so so pretty! I love it :]', '2007-10-14 04:02:45.000000', NULL, 1),
(4166135, 597569, 37444, '<td valign="top">A creative take on a common subject - well done - 9</td>', 'A creative take on a common subject - well done - 9', '2007-10-14 04:03:15.000000', NULL, 1),
(4166137, 598185, 83623, '<td valign="top">beautiful.<br/>I love the web! :]</td>', 'beautiful.I love the web! :]', '2007-10-14 04:04:44.000000', NULL, 1),
(4166138, 595706, 79532, '<td valign="top">Nice content, Shadow on Plant however takes away the impact of the visual.  Maybe shot a bit too early?</td>', 'Nice content, Shadow on Plant however takes away the impact of the visual.  Maybe shot a bit too early?', '2007-10-14 04:04:55.000000', NULL, 1),
(4166139, 595948, 37444, '<td valign="top">I am a lover of fisheyes! - 10</td>', 'I am a lover of fisheyes! - 10', '2007-10-14 04:05:27.000000', NULL, 1),
(4166140, 597779, 37444, '<td valign="top">You have Spring? You are so lucky!! :) 9</td>', 'You have Spring? You are so lucky!! :) 9', '2007-10-14 04:05:55.000000', NULL, 1),
(4166142, 597984, 79532, '<td valign="top">Nice Composition.  Picture just a bit too dark in places esp the right bottom leaf.</td>', 'Nice Composition.  Picture just a bit too dark in places esp the right bottom leaf.', '2007-10-14 04:07:53.000000', NULL, 1),
(4166143, 595037, 79532, '<td valign="top">Too Dark in places and overexposed background.  Focal point not very sharp.</td>', 'Too Dark in places and overexposed background.  Focal point not very sharp.', '2007-10-14 04:08:49.000000', NULL, 1),
(4166144, 596894, 37444, '<td valign="top">I wish all HDRs were as good as yours - this is wonderfully done! - 9</td>', 'I wish all HDRs were as good as yours - this is wonderfully done! - 9', '2007-10-14 04:12:07.000000', NULL, 1),
(4166146, 598126, 37444, '<td valign="top">very cool! - 9</td>', 'very cool! - 9', '2007-10-14 04:13:50.000000', NULL, 1),
(4166147, 598029, 37444, '<td valign="top">Nice contrast of the white linear and colorful curved. - 9</td>', 'Nice contrast of the white linear and colorful curved. - 9', '2007-10-14 04:14:24.000000', NULL, 1),
(4166148, 596187, 83623, '<td valign="top">This is a nice composition.<br/>Nothing is in focus though :/</td>', 'This is a nice composition.Nothing is in focus though :/', '2007-10-14 04:14:33.000000', NULL, 1),
(4166150, 596217, 37444, '<td valign="top">Wonderfully done, but that twig on the right distracts.</td>', 'Wonderfully done, but that twig on the right distracts.', '2007-10-14 04:15:36.000000', NULL, 1),
(4166152, 596661, 37444, '<td valign="top">Beautiful! 8</td>', 'Beautiful! 8', '2007-10-14 04:15:57.000000', NULL, 1),
(4166154, 596607, 83623, '<td valign="top">stunning! I love the colors and focus :]</td>', 'stunning! I love the colors and focus :]', '2007-10-14 04:16:32.000000', NULL, 1),
(4166155, 597409, 37444, '<td valign="top">If the red leaves were in focus, then this would be a 10 :)</td>', 'If the red leaves were in focus, then this would be a 10 :)', '2007-10-14 04:16:34.000000', NULL, 1),
(4166267, 597388, 84668, '<td valign="top">too noisy.</td>', 'too noisy.', '2007-10-14 08:41:14.000000', NULL, 1),
(4166411, 598430, 43073, '<td valign="top">Wonderful image, with subdued tones that play well with the subject.</td>', 'Wonderful image, with subdued tones that play well with the subject.', '2007-10-14 11:35:33.000000', NULL, 1),
(4166412, 598422, 43073, '<td valign="top">Delightful gradient in the sky adds impact, and the centered subject works here to emphasize the "aloneness" of the tree.</td>', 'Delightful gradient in the sky adds impact, and the centered subject works here to emphasize the "aloneness" of the tree.', '2007-10-14 11:36:18.000000', NULL, 1),
(4166414, 597569, 43073, '<td valign="top">Great tones and shades, perfect title.</td>', 'Great tones and shades, perfect title.', '2007-10-14 11:36:38.000000', NULL, 1),
(4166416, 597666, 43073, '<td valign="top">Subject well isolated, with nice detail and shades.</td>', 'Subject well isolated, with nice detail and shades.', '2007-10-14 11:37:20.000000', NULL, 1),
(4166418, 595300, 43073, '<td valign="top">The harshness of the light here accentuates the finality of the rose here for me, fading the color nicely.</td>', 'The harshness of the light here accentuates the finality of the rose here for me, fading the color nicely.', '2007-10-14 11:38:24.000000', NULL, 1),
(4166419, 597994, 43073, '<td valign="top">Nicely composed, with good choice of shutter speed to blur the water but leave the flora sharp.</td>', 'Nicely composed, with good choice of shutter speed to blur the water but leave the flora sharp.', '2007-10-14 11:39:08.000000', NULL, 1),
(4166421, 598315, 43073, '<td valign="top">Wonderful clarity here, nicely seen, composed and presented.</td>', 'Wonderful clarity here, nicely seen, composed and presented.', '2007-10-14 11:39:38.000000', NULL, 1),
(4166422, 597298, 43073, '<td valign="top">You''ve captured something almost sad about this flower, something that''s hidden just beneath the surface above the darkened greens of the leaves. Nice.</td>', 'You''ve captured something almost sad about this flower, something that''s hidden just beneath the surface above the darkened greens of the leaves. Nice.', '2007-10-14 11:40:39.000000', NULL, 1),
(4166423, 596633, 43073, '<td valign="top">Nice lines here dividing the image into sections, with an almost reflection of color on the ground matching what is still in the trees.</td>', 'Nice lines here dividing the image into sections, with an almost reflection of color on the ground matching what is still in the trees.', '2007-10-14 11:41:12.000000', NULL, 1),
(4166424, 595802, 43073, '<td valign="top">The soft and silky lines here are very pleasing to look at, well captured.</td>', 'The soft and silky lines here are very pleasing to look at, well captured.', '2007-10-14 11:41:36.000000', NULL, 1),
(4166427, 597974, 43073, '<td valign="top">Excellent choice of perspective and use of reflection, well placed for simplicity in the frame and good use of depth of field.</td>', 'Excellent choice of perspective and use of reflection, well placed for simplicity in the frame and good use of depth of field.', '2007-10-14 11:42:12.000000', NULL, 1),
(4166428, 598336, 43073, '<td valign="top">Good use of depth of field and monotone here to drive us to see what you wanted us to see.</td>', 'Good use of depth of field and monotone here to drive us to see what you wanted us to see.', '2007-10-14 11:42:48.000000', NULL, 1),
(4166430, 598264, 43073, '<td valign="top">Wow. Excellent. So easy to dismiss at first glance, but so many delights waiting if you''re willing to look further. Composition, by going down and left of the third intersection, forces the viewer into the blurred area, daring them to look. I''m glad I did, it took so long for the couple to come "clearly" into view. Different and moving.</td>', 'Wow. Excellent. So easy to dismiss at first glance, but so many delights waiting if you''re willing to look further. Composition, by going down and left of the third intersection, forces the viewer into the blurred area, daring them to look. I''m glad I did, it took so long for the couple to come "clearly" into view. Different and moving.', '2007-10-14 11:44:51.000000', NULL, 1),
(4166431, 598273, 43073, '<td valign="top">Neat image, floating as if disembodied. Well done.</td>', 'Neat image, floating as if disembodied. Well done.', '2007-10-14 11:45:16.000000', NULL, 1),
(4166462, 598168, 43073, '<td valign="top">Shades and colors, moving together, flowing, as does life. Nice.</td>', 'Shades and colors, moving together, flowing, as does life. Nice.', '2007-10-14 12:08:08.000000', NULL, 1),
(4166465, 596548, 43073, '<td valign="top">Death, portrayed as it occurs, without softness, or gentle tones. Harsh in color, light. Every choice made here makes this point. I wonder how many here, in their search for beauty, miss life when it is presented to them?</td>', 'Death, portrayed as it occurs, without softness, or gentle tones. Harsh in color, light. Every choice made here makes this point. I wonder how many here, in their search for beauty, miss life when it is presented to them?', '2007-10-14 12:14:08.000000', NULL, 1),
(4166466, 595194, 43073, '<td valign="top">Well seen and shot, with good use of depth of field for good impact.</td>', 'Well seen and shot, with good use of depth of field for good impact.', '2007-10-14 12:14:35.000000', NULL, 1),
(4166468, 595859, 43073, '<td valign="top">It is reaching, isn''t it? Out of the grass and the green, out of the dew. Well seen and shot.</td>', 'It is reaching, isn''t it? Out of the grass and the green, out of the dew. Well seen and shot.', '2007-10-14 12:15:06.000000', NULL, 1),
(4166469, 597332, 43073, '<td valign="top">Cool. I can never capture light like this, with so much impact and depth. Well done.</td>', 'Cool. I can never capture light like this, with so much impact and depth. Well done.', '2007-10-14 12:15:59.000000', NULL, 1),
(4166470, 598397, 43073, '<td valign="top">Good use of depth of field and composition, the line leading right across the image, the shadow emphasizing the flow.</td>', 'Good use of depth of field and composition, the line leading right across the image, the shadow emphasizing the flow.', '2007-10-14 12:16:38.000000', NULL, 1),
(4166472, 596661, 43073, '<td valign="top">So much orange against the depth of that blue, almost as if in battle, but in reality in harmony.</td>', 'So much orange against the depth of that blue, almost as if in battle, but in reality in harmony.', '2007-10-14 12:17:32.000000', NULL, 1),
(4166473, 596780, 43073, '<td valign="top">The harshness of the light here works well to bring the urban element out as primary here, the flora secondary to the hard concrete.</td>', 'The harshness of the light here works well to bring the urban element out as primary here, the flora secondary to the hard concrete.', '2007-10-14 12:18:11.000000', NULL, 1),
(4166474, 597337, 43073, '<td valign="top">Excellent composition and detail, the color against the dark provides extra impact.</td>', 'Excellent composition and detail, the color against the dark provides extra impact.', '2007-10-14 12:18:53.000000', NULL, 1),
(4166475, 595124, 43073, '<td valign="top">Green on green, with green. I like it, forces me to really look at the shades to find what''s there.</td>', 'Green on green, with green. I like it, forces me to really look at the shades to find what''s there.', '2007-10-14 12:22:30.000000', NULL, 1),
(4166489, 598014, 43073, '<td valign="top">The colors and faded shades here complement each other well.</td>', 'The colors and faded shades here complement each other well.', '2007-10-14 12:39:55.000000', NULL, 1),
(4166513, 596499, 43073, '<td valign="top">Beautiful, with the glow really emanating from within; the pedals'' shadows make this for me.</td>', 'Beautiful, with the glow really emanating from within; the pedals'' shadows make this for me.', '2007-10-14 12:56:29.000000', NULL, 1),
(4166515, 596510, 43073, '<td valign="top">So many sprites of color, dotted throughout; how easy to miss them if you don''t look (I''m glad you did).</td>', 'So many sprites of color, dotted throughout; how easy to miss them if you don''t look (I''m glad you did).', '2007-10-14 12:56:59.000000', NULL, 1),
(4166518, 596153, 43073, '<td valign="top">Deep reds and great textures, strong focus and good lines in a solid composition. Nicely shot.</td>', 'Deep reds and great textures, strong focus and good lines in a solid composition. Nicely shot.', '2007-10-14 12:58:59.000000', NULL, 1),
(4166520, 595165, 43073, '<td valign="top">The simplicity of this is perfect; a gentle and subtle shot.</td>', 'The simplicity of this is perfect; a gentle and subtle shot.', '2007-10-14 12:59:33.000000', NULL, 1),
(4166524, 596161, 43073, '<td valign="top">The background really adds a feeling of coolness to this image that emphasizes the main point well.</td>', 'The background really adds a feeling of coolness to this image that emphasizes the main point well.', '2007-10-14 13:00:40.000000', NULL, 1),
(4166553, 597312, 43073, '<td valign="top">Perfect. Stark, long reflections of life in shadow, my eye drawn toward the wall the shadows. Which is more real, which more alive. Delightful. 10.</td>', 'Perfect. Stark, long reflections of life in shadow, my eye drawn toward the wall the shadows. Which is more real, which more alive. Delightful. 10.', '2007-10-14 13:17:27.000000', NULL, 1),
(4166556, 598022, 43073, '<td valign="top">Good capture, with nice shades, though I am a bit distracted by the artifacts along the petals.</td>', 'Good capture, with nice shades, though I am a bit distracted by the artifacts along the petals.', '2007-10-14 13:18:12.000000', NULL, 1),
(4166557, 596183, 43073, '<td valign="top">A chaotic dance, and just as lovely.</td>', 'A chaotic dance, and just as lovely.', '2007-10-14 13:18:32.000000', NULL, 1),
(4166560, 597948, 43073, '<td valign="top">Good use of depth of field to blur the cones behind, holding the viewer''s attention with the front cone but daring them to look, to really look, behind.</td>', 'Good use of depth of field to blur the cones behind, holding the viewer''s attention with the front cone but daring them to look, to really look, behind.', '2007-10-14 13:19:19.000000', NULL, 1),
(4166562, 597442, 43073, '<td valign="top">As if another universe had opened itself up right in front of us, inviting us in. Wonderful choices here in composition and processing.</td>', 'As if another universe had opened itself up right in front of us, inviting us in. Wonderful choices here in composition and processing.', '2007-10-14 13:19:59.000000', NULL, 1),
(4166565, 598153, 43073, '<td valign="top">Bordered by chains of flowers, centered water -- one of our basic needs in life -- surrounded by green. Nice.</td>', 'Bordered by chains of flowers, centered water -- one of our basic needs in life -- surrounded by green. Nice.', '2007-10-14 13:20:54.000000', NULL, 1),
(4166569, 595123, 43073, '<td valign="top">Honestly, and this isn''t fair to you, but the first thing I thought is that those flowers are growing Dalmatian puppies in them . . . I do like this aside from that, though, the background delightfully sets off the silken purples.</td>', 'Honestly, and this isn''t fair to you, but the first thing I thought is that those flowers are growing Dalmatian puppies in them . . . I do like this aside from that, though, the background delightfully sets off the silken purples.', '2007-10-14 13:22:18.000000', NULL, 1),
(4166572, 595490, 43073, '<td valign="top">The night is never fully rid of the light, it hides, and comes out at opportune moments to shine brighter than the day. Wonderfully seen and captured.</td>', 'The night is never fully rid of the light, it hides, and comes out at opportune moments to shine brighter than the day. Wonderfully seen and captured.', '2007-10-14 13:23:05.000000', NULL, 1),
(4166573, 597448, 43073, '<td valign="top">Just the petals, just the ones closest, just enough to see, everything else faded, behind, lost. Just the petals. Wonderful.</td>', 'Just the petals, just the ones closest, just enough to see, everything else faded, behind, lost. Just the petals. Wonderful.', '2007-10-14 13:24:01.000000', NULL, 1),
