(4178339, 596221, 31403, '<td valign="top">I see you ARE still doing that DPC thing - this is a terrific image, this site doesn''t deserve it IMO.  Your talent is impressive and inspiring.</td>', 'I see you ARE still doing that DPC thing - this is a terrific image, this site doesn''t deserve it IMO.  Your talent is impressive and inspiring.', '2007-10-18 13:09:27.000000', NULL, 0),
