(4237736, 596607, 85566, '<td valign="top">This image is amazing! It''s really calming</td>', 'This image is amazing! It''s really calming', '2007-11-10 20:54:12.000000', NULL, 0),
(4242206, 598328, 43463, '<td valign="top">O.K. I have never seen this type of flower but I still find it beautiful for it''s beautiful red hues and it''s exotic look. BTW to my monitor the colors of red and green are bold and vibrant and don''t give the appearance of being overprocessed. While I love the hues and the shapes of this floral I am left wanting more. There is just too much surrounding landscape that takes the direct focus off this unusual &amp; beautiful plant. Draw your viewer closer so us all the beauty and intricate nature of this plant by either zooming in closer or cropping closer (a square crop would look rather nice and keep the focus on the Waratah). Bringing the viewer closer to the flower will also show us more detail of the ''texture'' that we only get a glimse of from this stand-off position. Seeing how the petals curve and loop would go a long way with increasing dramatic impact.</td>', 'O.K. I have never seen this type of flower but I still find it beautiful for it''s beautiful red hues and it''s exotic look. BTW to my monitor the colors of red and green are bold and vibrant and don''t give the appearance of being overprocessed. While I love the hues and the shapes of this floral I am left wanting more. There is just too much surrounding landscape that takes the direct focus off this unusual & beautiful plant. Draw your viewer closer so us all the beauty and intricate nature of this plant by either zooming in closer or cropping closer (a square crop would look rather nice and keep the focus on the Waratah). Bringing the viewer closer to the flower will also show us more detail of the ''texture'' that we only get a glimse of from this stand-off position. Seeing how the petals curve and loop would go a long way with increasing dramatic impact.', '2007-11-12 20:37:17.000000', NULL, 0),
(4249524, 597544, 81852, '<td valign="top">I like the colors a lot. I would have given this a 7 if I had gotten to vote in this one. Good job!</td>', 'I like the colors a lot. I would have given this a 7 if I had gotten to vote in this one. Good job!', '2007-11-15 14:20:13.000000', NULL, 0),
